import { useContext,useSate, useState } from "react";
import classes from "./UserForm.module.css";
import PasswordContext from "../store/password-context";


const UserForm = () => {
  const [title,settitle]=useSate('');
  const [password,setPassword]=useState("");
    const usePassword=useContext(PasswordContext);

    const titleHandler=(event)=>{
      settitle(event.target.value);
    }

    const passwordHandler=(event)=>{
      setPassword(event.target.value);
    }

  const submitHandler = (event) => {
    event.preventDefault();
    // const title = event.target.elements.title.value;
    // const password = event.target.elements.password.value;
    const id = Date.now() + Math.random().toString(36).substring(2);
    
     const item={
      id: id,
       
     }
     usePassword.addItem(item);
     usePassword.handleProduct();

  };

  const closeFormhandler=()=>{
    usePassword.closeForm();
  }

  return (
    <div>
      <div className={classes.form}>
        <form onSubmit={submitHandler}>
          <label>Title :</label>
          <input type="text" name="title" value={title} onChange={titleHandler} required></input>
          <label>Password:</label>
          <input type="text" name="password" value={password} onChange={passwordHandler} required></input>

          <button type="submit">Add</button>
          <button onClick={closeFormhandler}>X</button>
        </form>
      </div>
    </div>
  );
};
export default UserForm;
